<script setup lang="ts">
import { computed, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router';
import { ArrowUpRight, Building2, CircleHelp, LayoutDashboard, LogOut, Menu, Wallet, ShieldCheck, Sprout, Users, X } from 'lucide-vue-next';
import { useAuthStore } from '../stores/auth'; import { useLocale } from '../composables/useLocale'; import { initials } from '../utils/format'; import { errorMessage } from '../services/api';
const auth = useAuthStore(); const route = useRoute(); const router = useRouter(); const mobileOpen = ref(false); const error = ref(''); const signingOut = ref(false); const { t, toggle, locale } = useLocale();
const links = computed(() => [
  { to: '/', label: 'Overview', icon: LayoutDashboard, permission: 'dashboard.read' },
  { to: '/members', label: 'Members', icon: Users, permission: 'members.read' },
  { to: '/finance', label: 'Finance', icon: Wallet, permission: 'finance.read' },
  { to: '/loans', label: 'Loans', icon: Wallet, permission: 'finance.read' },
  { to: '/investments', label: 'Investments', icon: Building2, permission: 'finance.read' },
  { to: '/expenses', label: 'Expenses', icon: Wallet, permission: 'finance.read' },
  { to: '/bank', label: 'Bank', icon: Building2, permission: 'finance.read' },
  { to: '/approvals', label: 'Approvals', icon: ShieldCheck, permission: 'finance.approve' },
  { to: '/societies', label: 'Societies', icon: Building2, permission: 'societies.manage' },
  { to: '/users', label: 'Team & access', icon: ShieldCheck, permission: 'users.manage' },
  { to: '/my-profile', label: 'My dashboard', icon: LayoutDashboard, permission: 'profile.read', memberOnly: true },
].filter(l => auth.can(l.permission) && (!l.memberOnly || !auth.isStaff)));
const switching = ref(false);
async function switchSociety(event: Event) { switching.value = true; error.value = ''; try { await auth.switchSociety((event.target as HTMLSelectElement).value); } catch (e) { error.value = errorMessage(e); switching.value = false; } }
async function logout() { signingOut.value = true; try { await auth.logout(); await router.push('/login'); } catch (e) { error.value = errorMessage(e); } finally { signingOut.value = false; } }
</script>
<template><div class="app-shell"><button v-if="mobileOpen" class="sidebar-overlay" aria-label="Close navigation" @click="mobileOpen = false"></button><aside :class="['sidebar', { open: mobileOpen }]"><RouterLink class="brand" to="/"><span class="brand-mark"><Sprout :size="25" /></span>somity<span class="brand-dot">.</span></RouterLink><button class="mobile-close icon-button" aria-label="Close navigation" @click="mobileOpen = false"><X /></button><div class="workspace society-workspace"><span class="workspace-icon"><Building2 :size="20" /></span><label class="society-selector"><span>Current society</span><select aria-label="Current society" :value="auth.user?.societyId ?? ''" :disabled="switching || !auth.user?.societies.length" @change="switchSociety"><option v-if="!auth.user?.societyId" value="" disabled>Select a society</option><option v-for="society in auth.user?.societies" :key="society.id" :value="society.id">{{ society.name }}</option></select></label></div><small class="nav-label">WORKSPACE</small><nav aria-label="Main navigation"><RouterLink v-for="link in links" :key="link.to" :to="link.to" :class="{ selected: link.to === '/' ? route.path === '/' : route.path.startsWith(link.to) }" @click="mobileOpen = false"><component :is="link.icon" :size="19" />{{ t(link.label) }}</RouterLink></nav><div class="sidebar-note"><span class="note-icon"><ShieldCheck :size="20" /></span><strong>A secure foundation</strong><p>Your society. Your people.<br>One place to stay organized.</p><span>Phase 2 <ArrowUpRight :size="14" /></span></div><div class="sidebar-bottom"><CircleHelp :size="17" /><span>Society management</span><small>v1.1</small></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="Open navigation" @click="mobileOpen = true"><Menu /></button><span>{{ auth.user?.society?.name ?? 'Platform' }}</span><span class="slash">/</span><strong>{{ t(String(route.meta.title ?? 'Overview')) }}</strong></div><div class="topbar-actions"><button class="locale-button" @click="toggle">{{ locale === 'en' ? 'বাংলা' : 'English' }}</button><span class="topbar-divider"></span><span class="user-avatar">{{ initials(auth.user?.name ?? '') }}</span><div class="user-info"><strong>{{ auth.user?.name }}</strong><small>{{ auth.user?.roles[0]?.replaceAll('_', ' ') }}</small></div><button class="icon-button" :title="t('Sign out')" :aria-label="t('Sign out')" :disabled="signingOut" @click="logout"><LogOut :size="18" /></button></div></header><main><div v-if="error" class="alert error" role="alert">{{ error }}</div><RouterView :key="route.path" /></main><footer class="page-footer"><span>© {{ new Date().getFullYear() }} Somity. Built for your community.</span><span><span class="online-dot"></span> Phase 2 · Member savings</span></footer></div></div></template>
